const TP_LESSONS=[
 {title:'TradingView 가입과 차트 준비',short:'가입·로그인',desc:'무료 계정을 만들고 차트 화면을 여는 단계입니다. 실제 비밀번호는 이 연습장에 입력하지 않습니다.',code:'//@version=6\n// 1단계: 계정 준비 후 첫 스크립트 확인\nindicator("나의 첫 지표", overlay=true)\nplot(close)',command:'// 주석',explain:'// 뒤의 글은 실행되지 않는 설명입니다. 메모를 남길 때 사용합니다.',mission:'두 번째 줄에 // 가입 완료 주석을 추가합니다.',validation:'문법 정상 메시지가 유지되고 차트 모양은 변하지 않으면 주석이 올바르게 처리된 것입니다.',errorTest:'첫 줄의 6을 8로 바꾸면 버전 선언 오류가 표시되어야 합니다.',result:'준비가 끝났습니다. TradingView 차트를 열고 Pine Editor를 찾을 수 있습니다.'},
 {title:'indicator()와 plot() 첫 실행',short:'두 명령어 연습',desc:'첫 줄의 버전 선언은 그대로 두고 indicator()와 plot() 두 명령어만 입력하고 실행합니다.',code:'//@version=6\nindicator("Pine 시작", overlay=true)\nplot(close)',command:'indicator() · plot()',explain:'indicator()는 지표의 이름과 위치를 정하고, plot(close)는 종가를 선으로 표시합니다.',mission:'indicator()와 plot(close) 두 줄을 직접 다시 입력한 뒤 문법 검사·반영을 누릅니다.',validation:'오른쪽 실행 유형에 “지표 · Pine 시작”이 표시되고 종가선이 나타나면 통과입니다.',errorTest:'indicator를 indicater로 바꾸거나 plot을 plott로 바꾸면 알 수 없는 함수 오류가 표시되어야 합니다.',result:'indicator()로 만든 Pine 시작 지표에 plot(close) 종가선이 표시되었습니다.'},
 {title:'indicator() 옵션 확장 연습',short:'이름·패널·정밀도 설정',desc:'step-02의 기본 선언에서 더 나아가 정식 이름, 짧은 이름, 표시 패널, 소수 자릿수를 한 번에 설정합니다.',code:'//@version=6\nindicator("종가 위치와 표시 형식 실험", shorttitle="종가 실험", overlay=false, precision=2)\nplot(close)',command:'shorttitle · overlay · precision',explain:'shorttitle은 축약 이름, overlay는 표시 위치, precision은 출력값의 소수 자릿수를 정합니다.',mission:'shorttitle="종가 실험"을 shorttitle="CLOSE"로, overlay=false를 true로, precision=2를 0으로 바꿉니다.',validation:'오른쪽 실행 유형에 “CLOSE”, “가격 차트 위”, “소수 0자리”가 표시되고 마지막 값이 78로 보이면 통과입니다.',errorTest:'shorttitle을 shorttitel로 바꾸면 indicator()에 없는 파라미터 오류와 shorttitle 수정안이 나와야 합니다.',result:'indicator()의 이름·패널·정밀도 옵션이 적용되었습니다.'},
 {title:'plot()으로 종가 그리기',short:'plot()',desc:'plot()은 봉마다 달라지는 숫자 데이터를 선으로 연결합니다. close는 현재 계산 중인 각 봉의 종가이며, 열린 실시간 봉에서는 최신 체결 가격에 따라 계속 바뀝니다.',code:'//@version=6\nindicator("종가 선", overlay=true)\nplot(close)',command:'plot(close)',explain:'close는 종가의 연속 데이터(series)입니다. close[1]은 바로 이전 봉의 확정 종가이며, open·high·low를 넣으면 각각 시가·고가·저가를 그립니다.',mission:'plot(close)를 plot(high)로 바꾸어 각 봉의 고가를 그립니다.',validation:'파란 선이 위쪽으로 이동하고 오른쪽 마지막 값이 78에서 80으로 바뀌면 통과입니다.',errorTest:'plot(cloze)처럼 입력하면 cloze가 선언되지 않았다는 오류와 close 수정안이 나와야 합니다.',result:'각 캔들의 종가가 파란 선으로 연결되었습니다.'},
 {title:'색상과 선 굵기 바꾸기',short:'색상·굵기',desc:'plot()의 옵션으로 선을 알아보기 쉽게 꾸밉니다.',code:'//@version=6\nindicator("강조한 종가", overlay=true)\nplot(close, color=color.orange, linewidth=3)',command:'color · linewidth',explain:'color는 선 색, linewidth는 1~4 사이의 선 굵기입니다.',mission:'color.orange을 color.blue로, linewidth=3을 linewidth=1로 변경합니다.',validation:'주황색 굵은 선이 파란색 가는 선으로 즉시 바뀌고 문법 정상 상태가 유지되면 통과입니다.',errorTest:'color.blue를 color.bluu로 바꾸면 알 수 없는 색상 값과 color.blue 수정안이 표시되어야 합니다.',result:'주황색 굵은 종가 선이 표시되었습니다.'},
 {title:'변수로 계산 결과 저장하기',short:'변수·계산',desc:'반복해서 쓸 값은 이름을 붙여 변수에 저장합니다.',code:'//@version=6\nindicator("가격 중심선", overlay=true)\ncenter = (high + low) / 2\nplot(center, color=color.purple, linewidth=2)',command:'변수 = 계산식',explain:'center라는 상자에 고가와 저가의 평균을 저장했습니다.',mission:'계산식의 / 2를 / 500으로 바꾸어 산술식이 실제 출력에 반영되는지 확인합니다.',validation:'오른쪽 마지막 값이 78에서 0.312로 바뀌고 보라색 선의 축 범위가 크게 달라지면 통과입니다.',errorTest:'color.purple을 color.pu00rple로 바꾸면 해당 값 오류와 color.purple 수정안이 표시되어야 합니다.',result:'각 봉의 고가와 저가 중간값이 보라색으로 표시됩니다.'},
 {title:'input()으로 설정값 받기',short:'input()',desc:'사용자가 설정 창에서 기간이나 값을 바꿀 수 있게 만듭니다.',code:'//@version=6\nindicator("조절 가능한 평균", overlay=true)\nlength = input.int(10, "평균 기간", minval=2)\navg = ta.sma(close, length)\nplot(avg, color=color.blue, linewidth=2)',command:'input.int()',explain:'기본값, 화면에 보일 이름, 허용할 최솟값을 순서대로 정합니다.',mission:'input.int의 기본값 10을 20으로 바꾸어 평균 기간을 늘립니다.',validation:'파란 평균선이 더 부드러워지고 마지막 출력값이 달라지면 입력값이 계산에 반영된 것입니다.',errorTest:'minval을 minvall로 바꾸면 input.int()에 없는 파라미터 오류와 minval 수정안이 나와야 합니다.',result:'평균 기간을 사용자가 조절할 수 있게 되었습니다.'},
 {title:'ta.sma()로 이동평균선 만들기',short:'ta.sma()',desc:'단순 이동평균은 최근 N개 종가의 평균으로 추세를 부드럽게 보여줍니다.',code:'//@version=6\nindicator("두 이동평균", overlay=true)\nfast = ta.sma(close, 5)\nslow = ta.sma(close, 20)\nplot(fast, color=color.blue, linewidth=2)\nplot(slow, color=color.orange, linewidth=2)',command:'ta.sma(close, 기간)',explain:'기간이 짧으면 가격에 빠르게, 길면 천천히 반응합니다.',mission:'빠른 평균의 기간 5를 10으로 바꾸고 두 선의 간격을 비교합니다.',validation:'파란 선이 이전보다 부드러워지고 마지막 출력 또는 두 선 사이 간격이 달라지면 통과입니다.',errorTest:'ta.sma를 ta.smma로 바꾸면 알 수 없는 함수 오류와 ta.sma() 수정안이 표시되어야 합니다.',result:'5일선과 20일선이 함께 표시되어 추세 비교가 쉬워졌습니다.'},
 {title:'ta.crossover() 교차 조건 테스트',short:'교차 조건',desc:'짧은 평균선이 긴 평균선을 아래에서 위로 통과하는 순간을 조건으로 저장합니다.',code:'//@version=6\nindicator("이동평균 교차 조건", overlay=true)\nfast = ta.sma(close, 5)\nslow = ta.sma(close, 20)\nbuy = ta.crossover(fast, slow)\nplot(fast, color=color.blue)\nplot(slow, color=color.orange)',command:'ta.crossover()',explain:'첫 값이 두 번째 값을 아래에서 위로 통과한 봉에서만 true가 됩니다.',mission:'ta.crossover를 ta.crossunder로 바꾸어 하향 교차 조건을 계산합니다.',validation:'결과 설명이 “상향 교차”에서 “하향 교차”로 바뀌고 신호 횟수가 다시 계산되면 통과입니다.',errorTest:'plot(slow...) 한 줄을 삭제했을 때 문법은 정상이면서 주황색 선만 사라지는지도 확인합니다.',result:'두 이동평균과 교차 조건이 계산되었습니다.'},
 {title:'plotshape() 신호 표시 테스트',short:'신호 표시',desc:'앞 단계에서 만든 교차 조건을 삼각형 표식으로 차트에 표시합니다.',code:'//@version=6\nindicator("교차 신호 표시", overlay=true)\nfast = ta.sma(close, 5)\nslow = ta.sma(close, 20)\nbuy = ta.crossover(fast, slow)\nplot(fast, color=color.blue)\nplot(slow, color=color.orange)\nplotshape(buy, style=shape.triangleup, color=color.green, location=location.belowbar)',command:'plotshape()',explain:'조건이 true인 봉에 모양·색상·위치를 지정해 표식을 그립니다.',mission:'plotshape의 color.green을 color.red로 바꾸어 신호 표식 색을 변경합니다.',validation:'상향 교차 위치의 초록색 삼각형이 빨간색으로 바뀌면 plotshape 옵션이 반영된 것입니다.',errorTest:'shape.triangleup을 shape.triangleupp으로 바꾸면 모양 값 오류와 올바른 수정안이 나와야 합니다.',result:'상승 교차 봉 아래에 초록색 삼각형이 표시되었습니다.'},
 {title:'strategy() 첫 백테스트',short:'전략 테스트',desc:'지표를 전략으로 바꾸고 과거 데이터에서 가상의 진입·청산을 확인합니다.',code:'//@version=6\nstrategy("첫 이동평균 전략", overlay=true)\nfast = ta.sma(close, 5)\nslow = ta.sma(close, 20)\nbuy = ta.crossover(fast, slow)\nsell = ta.crossunder(fast, slow)\nif buy\n    strategy.entry("Long", strategy.long)\nif sell\n    strategy.close("Long")\nplot(fast, color=color.blue)\nplot(slow, color=color.orange)',command:'strategy.entry() · close()',explain:'조건이 true일 때 가상 진입하고 반대 교차에서 포지션을 닫습니다.',mission:'빠른 기간 5를 10으로, 느린 기간 20을 30으로 바꾸어 전략 민감도를 낮춥니다.',validation:'두 평균선 모양과 교차 신호 횟수가 달라지고 실행 유형이 계속 “전략”으로 표시되면 통과입니다.',errorTest:'strategy.entry 아래 줄의 들여쓰기를 제거하면 if 실행문 들여쓰기 오류가 표시되어야 합니다.',result:'과거 차트에 가상 매수·청산 지점과 간단한 성과가 표시됩니다.'}
];
